import{_ as e,o as n,c as r,ah as i}from"./chunks/framework.Yx0DUrwu.js";const d=JSON.parse('{"title":"免疫系统与微环境","description":"","frontmatter":{},"headers":[],"relativePath":"biology/immunology-microenvironment.md","filePath":"biology/immunology-microenvironment.md","lastUpdated":1787828101000}'),o={name:"biology/immunology-microenvironment.md"};function s(t,a,l,p,c,m){return n(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="免疫系统与微环境" tabindex="-1">免疫系统与微环境 <a class="header-anchor" href="#免疫系统与微环境" aria-label="Permalink to &quot;免疫系统与微环境&quot;">​</a></h1><p>免疫学是单细胞研究最常见、也最容易解释过度的场景之一。一个 T cell cluster 不只是一个名字，它背后牵涉发育谱系、抗原刺激、组织定位、细胞互作、炎症环境和代谢状态。</p><h2 id="免疫系统的两条主线" tabindex="-1">免疫系统的两条主线 <a class="header-anchor" href="#免疫系统的两条主线" aria-label="Permalink to &quot;免疫系统的两条主线&quot;">​</a></h2><div class="check-grid"><article><strong>先天免疫</strong><span>巨噬细胞、树突细胞、中性粒细胞、NK 细胞等快速响应病原体、损伤和炎症信号。</span></article><article><strong>适应性免疫</strong><span>T 细胞和 B 细胞通过抗原特异性受体形成更精细的识别、记忆和效应功能。</span></article></div><p>Janeway 和 Medzhitov 对先天免疫识别、模式识别受体和适应性免疫激活之间的关系做过奠基性阐述 [1]。读免疫单细胞数据时，可以把“细胞谱系”和“激活状态”分开看：谱系回答它是谁，状态回答它正在做什么。</p><h2 id="免疫细胞速查" tabindex="-1">免疫细胞速查 <a class="header-anchor" href="#免疫细胞速查" aria-label="Permalink to &quot;免疫细胞速查&quot;">​</a></h2><div class="flow-strip"><span>T cells：杀伤、辅助、调节和记忆</span><span>B cells：抗体、抗原呈递和浆细胞分化</span><span>NK cells：天然杀伤和应激识别</span><span>Monocytes：循环髓系前体与炎症响应</span><span>Macrophages：吞噬、修复、抗原呈递</span><span>Dendritic cells：抗原呈递和 T cell priming</span><span>Neutrophils：急性炎症和颗粒酶效应</span><span>Mast cells：过敏、屏障和组织炎症</span></div><h2 id="免疫微环境" tabindex="-1">免疫微环境 <a class="header-anchor" href="#免疫微环境" aria-label="Permalink to &quot;免疫微环境&quot;">​</a></h2><p>微环境指细胞周围的组织生态：免疫细胞、基质细胞、内皮细胞、肿瘤细胞、细胞外基质、细胞因子、代谢条件和空间位置共同决定细胞状态。肿瘤免疫微环境尤其重要，因为免疫浸润、耗竭、抗原呈递、Treg、髓系抑制和空间排斥都会影响治疗响应。</p><p>Binnewies 等人在 <em>Nature Medicine</em> 综述中把肿瘤免疫微环境整理为动态生态系统，强调免疫细胞、肿瘤细胞和基质成分之间的互作 [2]。单细胞研究常用这个视角解释不同细胞群之间的配体-受体通讯、耗竭状态和炎症程序。</p><h2 id="t-cell-状态不要只靠一个-marker" tabindex="-1">T cell 状态不要只靠一个 marker <a class="header-anchor" href="#t-cell-状态不要只靠一个-marker" aria-label="Permalink to &quot;T cell 状态不要只靠一个 marker&quot;">​</a></h2><div class="doc-callout warning"><strong>PDCD1 高不等于一句话“耗竭”</strong><p>T cell exhaustion 需要结合多个抑制受体、效应分子、转录因子、克隆扩增、组织环境和功能证据。单个 marker 只能提示方向。</p></div><h2 id="单细胞免疫分析的解释路径" tabindex="-1">单细胞免疫分析的解释路径 <a class="header-anchor" href="#单细胞免疫分析的解释路径" aria-label="Permalink to &quot;单细胞免疫分析的解释路径&quot;">​</a></h2><div class="flow-strip"><span>先分谱系</span><span>再看亚群</span><span>检查激活/耗竭/干扰素状态</span><span>结合样本和疾病分组</span><span>看空间或组织来源</span><span>用 marker 支撑命名</span><span>保留 ambiguous 细胞</span><span>回到功能验证</span></div><h2 id="深入阅读路线" tabindex="-1">深入阅读路线 <a class="header-anchor" href="#深入阅读路线" aria-label="Permalink to &quot;深入阅读路线&quot;">​</a></h2><div class="path-grid"><a href="/biology/immunology-roadmap"><strong>Janeway 免疫学学习图谱</strong><span>先建立免疫系统整体地图，再进入固有免疫、抗原识别、淋巴细胞发育和疾病免疫。</span></a><a href="/biology/innate-immunity"><strong>固有免疫</strong><span>理解 PRR、补体、炎症、干扰素、NK 和 ILC，适合解释髓系与组织炎症状态。</span></a><a href="/biology/adaptive-effector-immunity"><strong>适应性免疫应答</strong><span>理解 T/B 细胞如何被启动、分化、产生效应功能和形成记忆。</span></a><a href="/biology/mucosal-disease-immunotherapy"><strong>黏膜免疫、疾病与治疗</strong><span>把免疫耐受、炎症性疾病、疫苗和肿瘤免疫治疗放回真实组织场景。</span></a></div><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>先天免疫和适应性免疫的主要差异是什么？</li><li>为什么细胞类型和细胞状态要分开解释？</li><li>肿瘤免疫微环境包含哪些非免疫成分？</li><li>为什么单个 marker 不足以给 T cell 状态下结论？</li></ol><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><p>[1] Janeway, C. A. Jr. &amp; Medzhitov, R. Innate immune recognition. <em>Annual Review of Immunology</em> 20, 197-216 (2002). <a href="https://www.annualreviews.org/doi/10.1146/annurev.immunol.20.083001.084359" target="_blank" rel="noreferrer">Annual Reviews</a></p><p>[2] Binnewies, M. et al. Understanding the tumor immune microenvironment (TIME) for effective therapy. <em>Nature Medicine</em> 24, 541-550 (2018). <a href="https://www.nature.com/articles/s41591-018-0014-x" target="_blank" rel="noreferrer">Nature Medicine</a></p>',21)])])}const u=e(o,[["render",s]]);export{d as __pageData,u as default};
